        html,
        body {
            margin: 0;
            padding: 0;
            width: 100%;
            height: 100%;
        }

        :root {
            /* =================================================
               SAVED THEME VARIABLES
               These are changed by the theme system below.
               ================================================= */

            --accent1: #9b59b6;
            --accent2: #c084fc;

            --theme-bg1: #000000;
            --theme-bg2: #b700ff;

            --navbar-bg: rgba(20, 20, 20, 0.7);
            --navbar-border: rgba(255, 255, 255, 0.1);
        }

        body {
            font-family: "Lexend", sans-serif;
            overflow: hidden;
            cursor: url("/cursor/Arrow.cur"), auto;
            color: white;
        }

        /* =====================================================
           BACKGROUND
           ===================================================== */

        #bg {
            position: fixed;
            inset: 0;
            z-index: -10;
            overflow: hidden;

            background:
                linear-gradient(
                    135deg,
                    var(--theme-bg1),
                    var(--theme-bg2)
                );
        }

        #bg .background-video {
            position: absolute;
            inset: 0;

            width: 100%;
            height: 100%;

            object-fit: cover;
            pointer-events: none;
        }

        /* =====================================================
           PAGE IFRAME
           ===================================================== */

        #pageFrame {
            position: fixed;
            inset: 0;

            width: 100%;
            height: 100%;

            border: none;
            z-index: 10;

            background: transparent;
            display: none;
        }

        /* =====================================================
           FIREFLIES
           ===================================================== */

        .firefly {
            position: absolute;

            border-radius: 50%;
            pointer-events: none;

            opacity: 0;

            filter: blur(0.3px);

            will-change: transform;
            animation-fill-mode: both;

            z-index: -5;
        }

        .firefly::after {
            content: "";

            position: absolute;
            inset: -3px;

            border-radius: 50%;

            background: inherit;

            opacity: 0.25;

            filter: blur(5px);
        }

        @keyframes fireflyMove {
            0% {
                transform:
                    translate(0px, 0px)
                    scale(0.8);

                opacity: 0;
            }

            8% {
                opacity: 0.2;
            }

            15% {
                transform:
                    translate(25px, -18px)
                    scale(1);

                opacity: 0.6;
            }

            35% {
                transform:
                    translate(60px, -40px)
                    scale(0.9);

                opacity: 0.85;
            }

            55% {
                transform:
                    translate(95px, -70px)
                    scale(1.05);

                opacity: 0.55;
            }

            75% {
                transform:
                    translate(130px, -105px)
                    scale(0.95);

                opacity: 0.75;
            }

            100% {
                transform:
                    translate(170px, -145px)
                    scale(0.7);

                opacity: 0;
            }
        }

        /* =====================================================
           HOME
           ===================================================== */

        #homeOverlay {
            position: fixed;
