            z-index: 20;

            display: flex;

            justify-content: center;
            align-items: center;

            pointer-events: none;
        }

        .panel {
            background: transparent;

            padding: 40px 20px;

            border-radius: 90px;

            text-align: center;

            width: 150%;
            max-width: 700px;

            pointer-events: auto;
        }

        /* =====================================================
           LOGO
           ===================================================== */

        .logo {
            font-family: "Grandstander", cursive;

            font-size: 92px;
            font-weight: 300;

            color: white;

            text-rendering: geometricPrecision;

            text-shadow:
                0 0 15px rgba(255, 255, 255, 0.05),
                0 0 35px color-mix(
                    in srgb,
                    var(--accent1) 35%,
                    transparent
                );
        }

        .logo span {
            display: inline-block;
            text-rendering: geometricPrecision;
        }

        .logo span:nth-child(1) {
            transform:
                rotate(-6deg)
