                scaleY(1.08);
        }

        .logo span:nth-child(5) {
            transform:
                rotate(5deg)
                translateY(-2px)
                scaleY(0.92);
        }

        /* =====================================================
           QUICK OPTIONS
           ===================================================== */

        .quick-options {
            border-radius: 40px;

            font-family: "Grandstander", cursive;

            background-color: rgba(82, 82, 82, 0.2);

            padding-top: 20px;
            padding-left: 30px;
