        /* =====================================================
           NAVBAR
           ===================================================== */

        .navbar {
            position: fixed;

            bottom: 15px;
            left: 50%;

            transform:
                translateX(-50%);

            display: flex;

            gap: 8px;

            padding: 8px 12px;

            border-radius: 18px;

            background:
                var(--navbar-bg);

            backdrop-filter:
                blur(12px);

            border:
                1px solid
                var(--navbar-border);

            box-shadow:
                0 0 25px
                color-mix(
                    in srgb,
                    var(--accent1) 65%,
