            justify-content: center;

            border: none;

            background: transparent;

            cursor:
                url("/cursor/Hand.cur"),
                pointer;

            border-radius: 10px;

            transition: 0.2s;
        }

        .nav-btn:hover {
            background:
                color-mix(
                    in srgb,
                    var(--accent1) 15%,
                    rgba(255,255,255,0.08)
                );
        }

        .nav-btn-img {
            width: 18px;
            height: 18px;

            opacity: 0.8;

            display: flex;

            align-items: center;
            justify-content: center;
        }

        .nav-btn-game {
            opacity: 0.8;

            height: 18px;
            width: 22px;
        }

        /* =====================================================
           SECRET 676767
           ===================================================== */

        #secret676767 {
            position: fixed;
            inset: 0;

            z-index: 1000000;

            display: none;

            background: #000;

            color: white;

            align-items: center;
            justify-content: center;

            font-family:
                "Grandstander",
                cursive;

            font-size: 40px;
        }

        #secret676767.active {
            display: flex;
        }
/* =========================
